const AUTOGENERATED: &str = "permissions/autogenerated";

/// Remove the permission file of a command no longer listed, which
/// `tauri-build` would otherwise keep reading into the manifest.
fn remove_stale_permissions() {
    let Ok(entries) = std::fs::read_dir(AUTOGENERATED) else {
        return;
    };
    for entry in entries.flatten() {
        let path = entry.path();
        let listed = path
            .extension()
            .is_some_and(|extension| extension == "toml")
            && path
                .file_stem()
                .and_then(|stem| stem.to_str())
                .is_some_and(|stem| COMMANDS.contains(&stem));
        if !listed {
            std::fs::remove_file(&path)
                .unwrap_or_else(|error| panic!("{} is removable: {error}", path.display()));
        }
    }
}

fn main() {
    remove_stale_permissions();
    let attributes = tauri_build::Attributes::new()
        .app_manifest(tauri_build::AppManifest::new().commands(COMMANDS));
    if let Err(error) = tauri_build::try_build(attributes) {
        panic!("tauri-build failed: {error:#}");
    }
}
